pub fn dorian_izlude(ctx: &Ctx) -> Script {
    dorian_izlude_run(ctx, DorianIzludeStep::Start, Vec::new()).map(|_| ())
}

pub fn dorian_izlude_ontouch(ctx: &Ctx) -> Script {
    dorian_izlude_run(ctx, DorianIzludeStep::OnTouch, Vec::new()).map(|_| ())
}

