                            ctx.call(Function::DoNpcEvent, vec![Val::from("#ZGuard::OnDisable")])?;
                            ctx.call(Function::EnableNpc, vec![Val::from("Louis")])?;
                            ctx.call(Function::EnableNpc, vec![Val::from("Martha")])?;
